/** Ports contracts the generated types do not carry under these names; every other port type is imported from the generated contract where it is used. */
import type { ApprovalDecisionReply, PortConnection, PortRequest, Approval } from '@/generated/api-types';

/** Not generated: the environment's own peer endpoint answers a connection row with its signed assertion; the API's connection list never carries one. */
export interface PortPeer extends PortConnection { assertion: string }
/** Not generated by name: the generated approval narrowed to the port request its `port` kind carries. */
export type PortApproval = Omit<Approval, 'kind' | 'request'> & { kind: 'port'; request: PortRequest };
/** Not generated by name: the generated decision reply on a port approval, narrowed the same way, with the opening it decided. */
export type PortApprovalReply = PortApproval & { opening_result: NonNullable<ApprovalDecisionReply['opening_result']> | null };
